package cc.jumpkick.format;

import java.nio.charset.StandardCharsets;
import java.util.Locale;

/**
 * Whether a source says it was written by a program, so {@code jk format} leaves it as it is: a
 * generator rewrites the file on its next run, and a format pass over it is churn the author
 * cannot keep.
 *
 * <p>The test reads the file's leading comments, the ones before its first line of code, and
 * looks for the markers generators write there: {@code DO NOT EDIT} (protoc, Go's {@code Code
 * generated ... DO NOT EDIT.}, most in-house generators), {@code @generated} (Meta's, Android's
 * and many others'), or a comment line that starts {@code GENERATED by}, {@code Generated from},
 * {@code Auto-generated}, {@code This file was generated} and the like. Case does not matter, and
 * neither does where a line breaks: a marker on a 150-column first line counts exactly like the
 * same marker split over two short lines.
 *
 * <p>Only the header counts: a {@code DO NOT EDIT} in a comment further down a hand-written file,
 * or in a string, does not make it generated.
 */
final class GeneratedSource {

    private GeneratedSource() {}

    /** How far into a file the header may run; a generator's banner is well inside this. */
    static final int HEADER_LIMIT = 16 * 1024;

    /** How a generator's banner line begins, lower-cased, after its comment markers. */
    private static final String[] OPENINGS = {
        "generated by",
        "generated from",
        "generated with",
        "auto-generated",
        "autogenerated",
        "code generated by",
        "this file is generated",
        "this file was generated",
        "this file is auto-generated",
    };

    static boolean isGenerated(byte[] source) {
        int n = Math.min(source.length, HEADER_LIMIT);
        return isGenerated(new String(source, 0, n, StandardCharsets.UTF_8));
    }

    static boolean isGenerated(String source) {
        String header = leadingComments(source).toLowerCase(Locale.ROOT);
        if (header.contains("do not edit") || header.contains("@generated")) return true;
        for (String line : header.split("\n", -1)) {
            String t = line.strip();
            while (!t.isEmpty() && (t.charAt(0) == '*' || t.charAt(0) == '/' || t.charAt(0) == '#')) {
                t = t.substring(1).strip();
            }
            for (String opening : OPENINGS) {
                if (t.startsWith(opening)) return true;
            }
        }
        return false;
    }

    /**
     * The text of the comments before the first code: {@code //} lines and {@code /* … *\/} blocks
     * (javadoc included), with a leading {@code #!} line and blank lines between them. Each comment
     * contributes its own text and a line break.
     */
    static String leadingComments(String src) {
        var out = new StringBuilder();
        int i = 0;
        int n = Math.min(src.length(), HEADER_LIMIT);
        if (src.startsWith("﻿")) i = 1;
        if (src.startsWith("#!", i)) {
            int eol = src.indexOf('\n', i);
            i = eol < 0 ? n : eol + 1;
        }
        while (i < n) {
            char c = src.charAt(i);
            if (Character.isWhitespace(c)) {
                i++;
            } else if (src.startsWith("//", i)) {
                int eol = src.indexOf('\n', i);
                int end = eol < 0 ? n : Math.min(eol, n);
                out.append(src, i + 2, end).append('\n');
                i = end;
            } else if (src.startsWith("/*", i)) {
                int close = src.indexOf("*/", i + 2);
                int end = close < 0 ? n : Math.min(close, n);
                out.append(src, i + 2, end).append('\n');
                i = close < 0 ? n : close + 2;
            } else {
                break;
            }
        }
        return out.toString();
    }
}
